## This code was generated by copilot
## Extracts every .csv.gz file under a folder (default: the current folder), in parallel.

import argparse
import os
import gzip
import shutil
from multiprocessing import Pool


# Collect all .csv.gz file paths
def find_gz_files(root_dir):
    files = []
    for dirpath, _, filenames in os.walk(root_dir):
        for f in filenames:
            if f.endswith('.csv.gz'):
                full_path = os.path.join(dirpath, f)
                files.append(full_path)
    return files

# Extract a single .csv.gz file
def extract_gz_file(gz_path):
    out_path = gz_path[:-3]  # remove .gz
    try:
        with gzip.open(gz_path, 'rb') as f_in:
            with open(out_path, 'wb') as f_out:
                shutil.copyfileobj(f_in, f_out)
        return f"✓ Extracted: {gz_path}"
    except Exception as e:
        return f"✗ Failed: {gz_path}: {e}"

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description="Extract all .csv.gz files under a folder.")
    parser.add_argument("root_dir", nargs="?", default=".")
    args = parser.parse_args()

    all_gz_files = find_gz_files(args.root_dir)
    print(f"Found {len(all_gz_files)} .csv.gz files.\n")

    with Pool() as pool:
        for result in pool.imap_unordered(extract_gz_file, all_gz_files):
            print(result)